const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');

const service = new ProfileService({ displayName: 'before', tags: ['old'] });
assert.deepEqual(service.patch({ displayName: 'after' }), { displayName: 'after', tags: ['old'] });
assert.deepEqual(service.patch({ tags: ['new'] }), { displayName: 'after', tags: ['new'] });
const storedTags = service.profile.tags;
assert.equal(service.patch({}), service.profile);
assert.equal(service.profile.tags, storedTags);

const input = Object.freeze({ displayName: '  trimmed  ', tags: Object.freeze([' one ', 'two']) });
assert.deepEqual(service.patch(input), { displayName: 'trimmed', tags: ['one', 'two'] });
assert.notEqual(service.profile.tags, input.tags);
assert.deepEqual(input.tags, [' one ', 'two']);
const callerTags = ['separate'];
service.patch({ tags: callerTags });
callerTags.push('later');
assert.deepEqual(service.profile.tags, ['separate']);
assert.deepEqual(service.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
assert.deepEqual(service.patch(Object.assign(Object.create(null), { displayName: ' null prototype ' })), {
  displayName: 'null prototype', tags: [],
});
assert.deepEqual(service.patch({ tags: [] }).tags, []);
assert.equal(service.patch({ displayName: ' ' + 'a'.repeat(40) + ' ' }).displayName.length, 40);
assert.deepEqual(service.patch({ tags: ['a'.repeat(12), 'b', 'c', 'd', 'e'] }).tags, ['a'.repeat(12), 'b', 'c', 'd', 'e']);

const invalidInputs = [
  null, undefined, 1, 'text', true, [], () => {}, new Date(), Object.create({}),
  { extra: true }, { [Symbol('extra')]: true },
  Object.defineProperty({}, 'extra', { value: true }),
  { displayName: undefined }, { displayName: 12 }, { displayName: '' },
  { displayName: '  ' }, { displayName: 'a'.repeat(41) },
  { tags: undefined }, { tags: 'one' }, { tags: 12 },
  { tags: [1] }, { tags: [null] }, { tags: [''] }, { tags: ['  '] },
  { tags: ['a'.repeat(13)] }, { tags: ['one', ' one '] },
  { tags: ['a', 'b', 'c', 'd', 'e', 'f'] }, { tags: new Array(1) },
  { displayName: 'valid', tags: ['bad', 1] },
  { displayName: '', tags: ['valid'] },
];
for (const invalid of invalidInputs) {
  const profile = { displayName: 'before', tags: ['old'] };
  const service = new ProfileService(profile);
  const tags = profile.tags;
  assert.throws(() => service.patch(invalid), { name: 'Error', message: 'invalid profile' });
  assert.deepEqual(profile, { displayName: 'before', tags: ['old'] });
  assert.equal(profile.tags, tags);
}
